using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.ChangeTracking;

// 1. 租户信息与解析服务
public interface ITenantProvider
{
    string TenantId { get; }
    string ConnectionString { get; }
}

public class HttpTenantProvider : ITenantProvider
{
    private readonly IHttpContextAccessor _accessor;
    public HttpTenantProvider(IHttpContextAccessor accessor) => _accessor = accessor;

    public string TenantId => _accessor.HttpContext?.Request.Headers["X-Tenant-Id"].FirstOrDefault()
        ?? throw new InvalidOperationException("Missing X-Tenant-Id header");

    public string ConnectionString => $"Server=.;Database=tenant_{TenantId};Trusted_Connection=true;";
}

// 2. DbContext：QueryFilter + SaveChanges 自动注入
public class MultiTenantDbContext : DbContext
{
    private readonly ITenantProvider _tenantProvider;

    public MultiTenantDbContext(DbContextOptions<MultiTenantDbContext> options,
        ITenantProvider tenantProvider) : base(options)
    {
        _tenantProvider = tenantProvider;
    }

    public DbSet<Order> Orders => Set<Order>();
    public DbSet<Product> Products => Set<Product>();

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // 全局 QueryFilter：所有查询自动附加 TenantId 条件
        modelBuilder.Entity<Order>().HasQueryFilter(o => o.TenantId == _tenantProvider.TenantId);
        modelBuilder.Entity<Product>().HasQueryFilter(p => p.TenantId == _tenantProvider.TenantId);

        // 组合唯一索引：防止同租户内重复数据
        modelBuilder.Entity<Order>().HasIndex(o => new { o.TenantId, o.OrderNo }).IsUnique();
    }

    public override int SaveChanges()
    {
        InjectTenantId();
        return base.SaveChanges();
    }

    public override async Task<int> SaveChangesAsync(CancellationToken ct = default)
    {
        InjectTenantId();
        return await base.SaveChangesAsync(ct);
    }

    private void InjectTenantId()
    {
        // 新增实体自动写入 TenantId
        foreach (EntityEntry entry in ChangeTracker.Entries()
            .Where(e => e.State == EntityState.Added))
        {
            if (entry.Entity is ITenantEntity tenantEntity)
            {
                tenantEntity.TenantId = _tenantProvider.TenantId;
            }
        }

        // 可选：禁止修改 TenantId（防止实体"漂移"到其他租户）
        foreach (EntityEntry entry in ChangeTracker.Entries()
            .Where(e => e.State == EntityState.Modified))
        {
            if (entry.Entity is ITenantEntity)
            {
                entry.Property("TenantId").IsModified = false;
            }
        }
    }
}

// 3. 租户实体接口
public interface ITenantEntity
{
    string TenantId { get; set; }
}

public class Order : ITenantEntity
{
    public int Id { get; set; }
    public string TenantId { get; set; } = string.Empty;
    public string OrderNo { get; set; } = string.Empty;
    public decimal Amount { get; set; }
}

public class Product : ITenantEntity
{
    public int Id { get; set; }
    public string TenantId { get; set; } = string.Empty;
    public string Name { get; set; } = string.Empty;
}

// 4. DI 注册（ASP.NET Core）
public static class MultiTenantServiceCollectionExtensions
{
    public static IServiceCollection AddMultiTenantEfCore(this IServiceCollection services)
    {
        services.AddScoped<ITenantProvider, HttpTenantProvider>();
        services.AddDbContext<MultiTenantDbContext>((sp, options) =>
        {
            var tenant = sp.GetRequiredService<ITenantProvider>();
            options.UseSqlServer(tenant.ConnectionString);
        });
        return services;
    }
}
